def unit_of_work(metadata=None, timeout=None):
    if timeout is not None and timeout < 0:
        raise ValueError("Transaction timeout cannot be negative")
    def wrap(func):
        def transaction(tx, *args, **kwargs):
            with tx.begin(metadata=metadata, timeout=timeout):
                result = func(tx, *args, **kwargs)
                return result
        return transaction
    return wrap

