    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Create a dictionary to store the data
    data = {}

    # If no keys are provided, include all values
    if not keys:
        keys = self.keys()

    # Iterate over the keys and add the corresponding values to the dictionary
    for key in keys:
        # If the key is an integer, use it as an index
        if isinstance(key, int):
            try:
                data[self.fields[key]] = self[key]
            except IndexError:
                raise IndexError("Index out of bounds")
        # If the key is not an integer, use it as a field name
        else:
            try:
                data[key] = self[key]
            except KeyError:
                data[key] = None

    return data

