def shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if len(seq) == 1:
        return list(seq)

    output = list(seq)
    for i in range(1, len(seq)):
        idx = i % len(seq)
        output[i], output[idx] = output[idx], output[i]

    return output

