def mru_cache(maxsize=128, typed=False):
    def wrapper(func):
        # Define a datastructure to store the cache items
        class MRUCacheItem:
            def __init__(self, value, key):
                self.value = value
                self.key = key

        # Define a comparison function to compare two MRUCacheItems based on their last access time
        def compare_items(item1, item2):
            return item1.last_access_time - item2.last_access_time

        # Add a property to the wrapper function to act as the cache
        @property
        def cache(self):
            # Declare a list to store the cache items
            cache = []

            # Add the function as the first item in the cache
            cache.append(MRUCacheItem(func(), func.__name__))

            # Add other items from the cache if the cache is full
            while len(cache) >= maxsize:
                # Remove the least recently used item
                remove_item = None
                for item in cache:
                    if remove_item is None or compare_items(item, remove_item) > 0:
                        remove_item = item
                cache.remove(remove_item)

            return cache

        # Add a property to the wrapper function to act as the cached function
        @property
        def cached_func(self):
            # Define a function that wraps the original function
            def wrapper(*args, **kwargs):
                # Get the cache
                cache = self.cache

                # Find the function in the cache
                for item in cache:
                    if item.key == func.__name__ + str(args) + str(kwargs):
                        return item.value

                # If the function is not in the cache, call the original function and add the result to the cache
                value = func(*args, **kwargs)
                cache.append(MRUCacheItem(value, func.__name__ + str(args) + str(kwargs)))
                return value

            return wrapper

        return wrapper.cached_func

