def minimalBases(classes):
    # Create a dictionary to keep track of the base classes and their appearances
    base_dict = {}
    for cls in classes:
        for base in cls.__bases__:
            if base not in base_dict:
                base_dict[base] = 1
            else:
                base_dict[base] += 1

    # Sort the base classes by appearance, descending
    sorted_bases = sorted(base_dict.items(), key=lambda x: x[1], reverse=True)

    # Return the unique base classes and their minimum order
    return [base for base, count in sorted_bases if count == 1]

