def _explore_zipfile(zip_path):

    # Check if zip_path is a string
    if not isinstance(zip_path, str):
        raise TypeError("Expected argument 'zip_path' to be a string")

    # Open the zip file for reading
    try:
        with ZipFile(zip_path, 'r') as myzip:
            # Create a dictionary to store the data
            data = {}

            # Iterate over the files in the zip file and group them by their XML basename
            for file in myzip.namelist():
                if file.endswith(".xml"):
                    basename = file[:file.find(".") - 1]
                    if basename not in data:
                        data[basename] = []
                    data[basename].append(myzip.read(file))

            return data

    # Handle errors if there was a problem with the zip file
    except BadZipFile:
        raise Exception("The zip file appears to be corrupted or not in the expected format")
    except KeyError:
        raise Exception("Error reading data from zip file")

