def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dictionary from subparser name to argparse.ArgumentParser instance,
    give each requested action's subparser a shot at parsing all arguments. This allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dictionary mapping from subparser name to a parsed namespace of arguments, a list of remaining arguments not claimed by any subparser).
    """
    subparser_args = {}
    remaining_args = []
    for arg in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            try:
                # Try to parse the argument with the current subparser
                subparser_args[subparser_name] = subparser.parse_args([arg])
                break
            except SystemExit:
                # If the current subparser cannot parse the argument, ignore it and move on
                pass
        else:
            # If the argument was not claimed by any subparser, add it to the list of remaining arguments
            remaining_args.append(arg)
    return subparser_args, remaining_args

