def deep_merge_nodes(nodes):
    merged_nodes = []
    for node in nodes:
        key, value = node
        # If the key is not already in the merged nodes, add it
        if key not in [item[0] for item in merged_nodes]:
            merged_nodes.append((key, value))
            continue

        # Otherwise, find the node with the same key and deep merge the values
        for idx, (_, v) in enumerate(merged_nodes):
            if key == v:
                # Deep merge the values for the same key
                merged_nodes[idx] = (key, deep_merge_values(value.value, v.value))
                break

    return merged_nodes

