def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.
    """
    size_map = {
        "K": 1000,
        "M": 1000000,
        "G": 1000000000,
        "T": 1000000000000,
    }

    unit = size[-1]
    value = float(size[:-1])

    if unit not in size_map:
        raise ValueError(f"Invalid unit: {unit}")

    return int(value * size_map[unit])

