def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    import re

    # Prepare the regex patterns based on the platform
    if platform == 'this':
        posix_pattern = re.compile(r''' (?x) # POSIX pattern
            (
                \G (\\ [\\"'] | [^\s'"\\])+ |         # quotes and escaped characters
                (?= [^\\]\s | \Z) \s*            |     # non-escaped whitespace
                [^\s'\\]+ |                        # non-whitespace
                ' (?: "" | [^'] | \\. | $ )+ |     # quoted string
                " (?: \\. | [^\""] | $ )+         # quoted string
            )+ \s*?
        ''')
        cmd_pattern = re.compile(r''' (?x) # Windows/CMD pattern
            (
                \G [^\s()]+ |                      # non-whitespace
                \( ( [^()]* | \g<1> )+ \) |       # parentheses
                ["'] ( [^"'] | \\. | \g<1> )+ ["'] # quoted string
            )+ \s*?
        ''')
    elif platform == 1:
        # POSIX pattern
        posix_pattern = re.compile(r''' (?x)
            (
                \G [^\\\s] | ( \\ [\\"] ) |          # not whitespace or escaped buttons
                \s+ (\\ [\\"] )? |                   # whitespace separator
                [^"]["'] |                          # non-quoted character
                " ( \\. | [^"$] )+ " |              # quoted string
                ' ( \\. | [^'$\n] )+ '              # quoted string
            )+ \s*?
        ''')
        # cmd_pattern = cmd_pattern_for_platform_1
    elif platform == 0:
        # Windows/CMD pattern
        posix_pattern = re.compile(r''' (?x)
            (
                No pattern for this platform (platform == 0)
            )+ \s*?
        ''')

    # Split the string
    if platform == 1:
        return cmd_pattern.split(s)    
    elif platform == 0:
        return posix_pattern.split(s)
    else:
        return posix_pattern.split(s)

