def parse_frequency(frequency: str) -> Optional[timedelta]:
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        number, unit = frequency.split()
        number = int(number)
        if unit.lower() == "days":
            return timedelta(days=number)
        elif unit.lower() == "weeks":
            return timedelta(weeks=number)
        elif unit.lower() == "months":
            return timedelta(weeks=number * 4)
        elif unit.lower() == "years":
            return timedelta(weeks=number * 52)
        else:
            raise ValueError("Invalid unit of time: {}".format(unit))
    except ValueError as e:
        raise ValueError("Invalid frequency: {}".format(frequency)) from e
    except:
        raise ValueError("Invalid frequency: {}".format(frequency))

