def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not isinstance(hist, Histogram):
        raise TypeError("hist must be a Histogram")
    if make_value is not None and not callable(make_value):
        raise TypeError("make_value must be a function or None")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be one of 'left', 'right', 'middle'")
    if not isinstance(field_names, tuple) or len(field_names) != 2:
        raise ValueError("field_names must be a tuple of length 2")
    if not isinstance(scale, (bool, type(None))):
        raise TypeError("scale must be a bool or None")

    # Set make_value to the default if it's not provided
    if make_value is None:
        make_value = lambda x: x

    # Create a graph with the appropriate field names
    graph = Graph(field_names=field_names)

    # Add data points to the graph for each bin in the histogram
    for i, bin in enumerate(hist.bins):
        x_coord = i if get_coordinate == "left" else i + 0.5
        y_coord = make_value(bin.value)
        graph.add_data_point([x_coord, y_coord])

    # Set the graph's scale if necessary
    if scale is True:
        graph.scale = hist.scale

    return graph

