def verifyObject(iface, candidate, tentative=False):
    # Check if the candidate implements the interface
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid("Candidate does not implement the interface")

    # Check that all required methods are present and have the correct signature
    for method in iface.methods:
        if not hasattr(candidate, method.name):
            raise zope.interface.Invalid(f"Candidate does not define method {method.name}")
        candidate_method = getattr(candidate, method.name)
        if not zope.interface.verifyClass(candidate_method, method, strict=True):
            raise zope.interface.Invalid(f"Candidate's implementation of method {method.name} is invalid")

    # Check that all required attributes are present and of the correct type
    for attribute in iface.attributes:
        if not hasattr(candidate, attribute.name):
            raise zope.interface.Invalid(f"Candidate does not define attribute {attribute.name}")
        candidate_attribute = getattr(candidate, attribute.name)
        if not zope.interface.verifyClass(candidate_attribute, attribute, strict=True):
            raise zope.interface.Invalid(f"Candidate's implementation of attribute {attribute.name} is invalid")

    # All checks passed
    return True

