def determineMetaclass(bases, explicit_mc=None):
    # Check if explicit metaclass was provided
    if explicit_mc is not None:
        return explicit_mc

    # Check if any of the bases has a __metaclass__ attribute set
    for base in bases:
        if hasattr(base, "__metaclass__"):
            return base.__metaclass__

    # If no explicit metaclass was provided and none of the bases have a __metaclass__ attribute set, use the type of the first base as the metaclass
    return type(bases[0])

