def popitem(self):
    # 1. Check if the cache is empty
    if not self.cache:
        raise KeyError("Cache is empty")
    # 2. Find the least recently used key-value pair
    lru_pair = None
    for key, value in self.cache.items():
        if lru_pair is None or lru_pair[1] < value[1]:
            lru_pair = (key, value)
    # 3. Remove the LRU key-value pair from the cache
    self.cache.pop(lru_pair[0])
    # 4. Return the LRU key-value pair
    return lru_pair

