def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    import requests

    try:
        response = requests.get(f"https://webfinger.net/.well-known/webfinger?resource={handle}")
        if response.ok:
            doc = response.json()
            if doc["links"][0]["rel"] == "self" and doc["links"][0]["href"].endswith(".json"):
                return doc["links"][0]["href"]
        else:
            print("Error: Retrieved document is not in JSON format.")
    except requests.exceptions.ConnectionError:
        print("Error: Cannot connect to webfinger.net.")
    return None

